      "en": "",
      "count": 0,
      "ipcCode": "",
      "fTerm": "LIME; MAGNESIA; SLAG; CEMENTS; COMPOSITIONS THEREOF, e.g. MORTARS, CONCRETE OR LIKE BUILDING MATERIALS; ARTIFICIAL STONE; CERAMICS (devitrified glass-ceramics <b>C03C 10/00</b>); REFRACTORIES (alloys based on refractory metals <b>C22C</b>); TREATMENT OF NATURAL STONE<b>[4]</b><br><br><b><u>Note(s)</u></b><br><br><ul type=\"\"1\"\"><li>In this subclass, the following terms or expressions are used with the meanings indicated:<b>[6]</b><ul type=\"\"disc\"\"><li>&quot;fillers&quot; includes pigments, aggregates and fibrous reinforcing materials;</li><li>&quot;active ingredients&quot; includes processing aids or property improvers, e.g. grinding aids used after the burning process or used in the absence of a burning process;</li><li>&quot;mortars&quot;, &quot;concrete&quot; and &quot;artificial stone&quot; are to be considered as a single group of materials, and therefore, in the absence of an indication to be contrary, they include mortar, concrete and other cementitious compositions.</li></ul></li></ul><br><br><b><u>Subclass indexes</u></b><br><table width=\"100%\"><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">LIME, MAGNESIA; SLAG</td><td><b>2/00</b>; <b>5/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">CEMENTS</td><td><b>7/00-12/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">MORTARS; CONCRETE; ARTIFICIAL STONE</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Compositions</td><td><b>26/00-32/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Fillers</td><td><b>14/00-20/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Active ingredients</td><td><b>22/00</b>, <b>24/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Porous products</td><td><b>38/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Influencing or modifying the properties of mortars</td><td><b>40/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">After-treatment</td><td><b>41/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">CERAMICS</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Clay-wares</td><td><b>33/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Other ceramics</td><td><b>35/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Joining</td><td><b>37/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Porous products</td><td><b>38/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">After-treatment</td><td><b>41/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">TREATMENT OF NATURAL STONE</td><td><b>41/00</b></td></p></tr></table>",
