      "ja": "モルタル，コンクリート，または人造石のための充填材としての物質であって，グループＣ０４Ｂ１４／００～Ｃ０４Ｂ１８／００の２以上に属するとともに形状または粒度分布に特徴のあるものの使用；モルタル，コンクリートまたは人造石に対するグループＣ０４Ｂ１４／００～Ｃ０４Ｂ１８／００の２以上に属する物質の充てん性を向上させるのに特に適合する処理；物質の膨張または解繊（建築材料用補強要素Ｅ０４Ｃ５／００）［４］",
      "en": "Use of materials as fillers for mortars, concrete or artificial stone according to more than one of groups C04B 14/00-C04B 18/00 and characterised by shape or grain distribution; Treatment of materials according to more than one of the groups C04B 14/00-C04B 18/00 specially adapted to enhance their filling properties in mortars, concrete or artificial stone; Expanding or defibrillating materials (reinforcing elements for building&nbsp;E04C 5/00) [4]",
      "count": 37,
      "ipcCode": "C04B20/00",
      "fTerm": "4G112",
      "childFlag": 0,
