    "C04B40/00\\": {
      "code": "C04B40/00\\",
      "level": 0,
      "parent": null,
      "ja": "モルタル組成物，コンクリート組成物または人造石組成物の性質，例．凝結もしくは硬化性，に影響を与えるかそれを変化させるためのプロセス一般（活性成分の選択によるものＣ０４Ｂ２２／００～Ｃ０４Ｂ２４／００；明確に規定された組成物の硬化Ｃ０４Ｂ２６／００～Ｃ０４Ｂ２８／００；多孔質，細胞状または軽量化するものＣ０４Ｂ３８／００）［４，６］",
      "en": "Processes, in general, for influencing or modifying the properties of mortars, concrete or artificial stone compositions, e.g. their setting or hardening ability (by selecting active ingredients C04B 22/00-C04B 24/00; hardening of a well-defined composition C04B 26/00-C04B 28/00; making porous, cellular or lightening C04B 38/00) [4,6]",
      "count": 1006,
      "ipcCode": "C04B40/00",
      "fTerm": "4G112",
      "childFlag": 0,
      "sourceFile": "fi_C04B.txt",
      "kind": "fi"
    },
